import{_ as i,c as a,o as e,ag as t}from"./chunks/framework.B3RpK1bM.js";const p=JSON.parse('{"title":"参与贡献","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/contributing.md","filePath":"zh_CN/contributing.md","lastUpdated":1769658044000}'),o={name:"zh_CN/contributing.md"};function r(n,l,s,c,d,h){return e(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="参与贡献" tabindex="-1">参与贡献 <a class="header-anchor" href="#参与贡献" aria-label="Permalink to &quot;参与贡献&quot;">​</a></h1><p><a href="./">返回目录</a></p><p>参与项目贡献是一个难度不小的工作，尽管如此，我们整理了不同难度的工作内容鼓励大家参与其中.</p><h2 id="简单任务" tabindex="-1">简单任务 <a class="header-anchor" href="#简单任务" aria-label="Permalink to &quot;简单任务&quot;">​</a></h2><ol><li>阅读说明书和wiki文档，修复文档错误和你发现不清楚的地方，并提交到Pull Requests.</li><li>在你感兴趣的领域制作ezgal的相关教程、介绍、节目，或者帮助别人一起，如果是公开的，欢迎提交到<code>cryingnights7v@gmail.com</code>.</li><li>尝试跑起来你的第一个ezgal框架项目，过程中出现任何问题欢迎反馈到issues.</li></ol><h2 id="中等任务" tabindex="-1">中等任务 <a class="header-anchor" href="#中等任务" aria-label="Permalink to &quot;中等任务&quot;">​</a></h2><ol><li>参与讨论ezgal解释器的语法设计等相关事宜，欢迎分享大家的独到简介.</li><li>试着修复一些现有问题，比如issues中的报告，制作属于自己的Pull Requests.</li><li>分享使用ezgal开发的游戏，我们欢迎各种优秀的作品，优秀的作品可以通过我们的通道进行展示曝光.</li></ol><h2 id="高级任务" tabindex="-1">高级任务 <a class="header-anchor" href="#高级任务" aria-label="Permalink to &quot;高级任务&quot;">​</a></h2><ol><li>参与构建ezgal游戏框架的开发生态.</li><li>联系我们<code>cryingnights7v@gmail.com</code>，参与项目安全相关维护工作.</li><li>试着让ezgal变得更好，试着参与我们的编辑器开发相关工作.</li><li>参与我们的里程规划.</li></ol><h1 id="标签说明" tabindex="-1">标签说明 <a class="header-anchor" href="#标签说明" aria-label="Permalink to &quot;标签说明&quot;">​</a></h1><p>我们按需求定义了4组标签：</p><ul><li>fix: 项目需要修正</li><li>new: 项目新增功能</li><li>bug: 项目存在错误</li><li>cve: 存在危害级别错误</li></ul><p>按系统定义了3组标签：</p><ul><li>os: android</li><li>os :Linux</li><li>os: windows</li></ul><p>按项目类别定义了：</p><ul><li>CI/CD: 问题来源于控制流</li><li>Ezgal: 问题来源于框架本体</li><li>Ezlang: 问题来源于解释器</li></ul><p>便于大家在讨论和贡献中筛选自己擅长的工作.</p>',17)])])}const _=i(o,[["render",r]]);export{p as __pageData,_ as default};
